/**
 * roleAvatars — Undercover role-card image registry (web: WebP)
 *
 * Web uses compressed 512px WebP avatars generated by scripts/process_avatars.py.
 * See roleAvatars.ts for the native variant (raw PNG).
 */

import type { UndercoverRole } from '@game-judge/game-engine/games/undercover/public';

import blank from '../../../../assets/avatars/web/blank.webp';
import civilian from '../../../../assets/avatars/web/civilian.webp';
import undercover from '../../../../assets/avatars/web/undercover.webp';

const UNDERCOVER_ROLE_IMAGE_MAP: Record<UndercoverRole, number> = {
  civilian,
  undercover,
  blank,
};

/** Resolve Undercover role IDs to the game's hand-drawn role-card assets. */
export function getRoleAvatar(roleId: UndercoverRole): number {
  return UNDERCOVER_ROLE_IMAGE_MAP[roleId];
}
